/* Broadcastwell answer record, brand system 3.0.2. Generated by tools/brand-build.mjs from
   brand/answer-record.mjs. Do not edit. Plain script for static surfaces: defines BwAnswerRecord and
   wires every [data-bw-answer-record] figure already in the page (the "Read as a table" control and
   the phone rule). No dependencies, no inline styles. */
(function (root) {
"use strict";
// BEGIN answer-record core
const AR_ENGINES = ["ChatGPT", "Claude", "Perplexity", "Google AI Overviews", "Google AI Mode"];
const AR_PALETTE = { paper: "#FFFFFF", ink: "#0B1220", inkSecondary: "#4A5568", line: "#7F8BA0", accent: "#1D4ED8", dataBlue: "#3B82F6" };
const AR_GEOMETRY = { viewBox: 640, center: 320, innerRadius: 112, outerRadius: 272, singleRadius: 200, gapDegrees: 64, spokeInset: 24, spokeOutset: 16, markMax: 18, markRatio: 0.5, minMarkPixels: 8, openStroke: 2.5, barStroke: 3 };
const AR_NOT_DRAWN = ["vantaa tax", "neurvalis", "valren atelier"];
const AR_SAMPLE_LABEL = "Sample data, fictional company";
const AR_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function arEscape(value) {
  return String(value == null ? "" : value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function arNum(value) {
  const rounded = Math.round(value * 100) / 100;
  return String(Object.is(rounded, -0) ? 0 : rounded);
}

function arDate(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ""));
  return m ? Number(m[3]) + " " + AR_MONTHS[Number(m[2]) - 1] + " " + m[1] : String(iso || "");
}

function arDates(list) {
  const dates = (list || []).map(arDate);
  if (dates.length < 2) return dates.join("");
  return dates.slice(0, -1).join(", ") + " and " + dates[dates.length - 1];
}

function arList(items) {
  if (items.length < 2) return items.join("");
  return items.slice(0, -1).join(", ") + " and " + items[items.length - 1];
}

function arValidate(record) {
  const problems = [];
  if (!record || typeof record !== "object") return ["record must be an object"];
  if (!record.subject || typeof record.subject !== "string") problems.push("subject is required");
  else if (AR_NOT_DRAWN.indexOf(record.subject.trim().toLowerCase()) >= 0) problems.push("a client's record is never drawn");
  if (record.sample !== true && /kalvenor/i.test(String(record.subject || ""))) problems.push("the Kalvenor record must be marked sample: true");
  const engines = Array.isArray(record.engines) ? record.engines : [];
  if (!engines.length) problems.push("engines must list at least one engine");
  let last = -1;
  engines.forEach(function (engine) {
    const at = AR_ENGINES.indexOf(engine);
    if (at < 0) problems.push("unknown engine " + engine);
    else if (at <= last) problems.push("engines must follow the order " + AR_ENGINES.join(", "));
    last = Math.max(last, at);
  });
  const questions = Array.isArray(record.questions) ? record.questions : [];
  if (questions.length < 1 || questions.length > 64) problems.push("questions must hold 1 to 64 buyer questions");
  questions.forEach(function (q, i) {
    if (!q || !q.text) problems.push("question " + (i + 1) + " needs its text");
    const marks = (q && q.marks) || {};
    Object.keys(marks).forEach(function (engine) {
      if (engines.indexOf(engine) < 0) problems.push("question " + (i + 1) + " has a mark for an engine not in the record: " + engine);
      if (!arReadMark(marks[engine], record.repeats).valid) problems.push("question " + (i + 1) + " has an invalid mark for " + engine);
    });
  });
  const c = record.caption || {};
  ["release", "category", "base", "source_url"].forEach(function (key) { if (!c[key]) problems.push("caption." + key + " is required"); });
  if (!Array.isArray(c.dates) || !c.dates.length || c.dates.some(function (d) { return !/^\d{4}-\d{2}-\d{2}$/.test(String(d)); })) problems.push("caption.dates must list ISO dates");
  if (c.source_url && !/^https:\/\//.test(c.source_url)) problems.push("caption.source_url must be an https URL");
  return problems;
}

// Returns { state: "named" | "not_named" | "unavailable", named, of, valid }.
function arReadMark(mark, repeats) {
  if (mark === "named") return { state: "named", named: 1, of: 1, valid: true, counted: false };
  if (mark === "not_named") return { state: "not_named", named: 0, of: 1, valid: true, counted: false };
  if (mark === "unavailable" || mark === undefined || mark === null) return { state: "unavailable", named: 0, of: 0, valid: mark !== null, counted: false };
  let named = null, of = null;
  if (typeof mark === "number") { named = mark; of = Number(repeats) || 1; }
  else if (typeof mark === "object") { named = Number(mark.named); of = Number(mark.of); }
  if (!Number.isInteger(named) || !Number.isInteger(of) || named < 0 || of < 0 || named > of) return { state: "unavailable", named: 0, of: 0, valid: false, counted: true };
  if (of === 0) return { state: "unavailable", named: 0, of: 0, valid: true, counted: true };
  return { state: named * 3 >= of * 2 ? "named" : "not_named", named: named, of: of, valid: true, counted: true };
}

function arStats(record) {
  const engines = record.engines;
  const perEngine = engines.map(function () { return { named: 0, of: 0 }; });
  const perQuestion = record.questions.map(function (q) {
    const row = { named: 0, of: 0, cells: [] };
    engines.forEach(function (engine, k) {
      const m = arReadMark((q.marks || {})[engine], record.repeats);
      row.cells.push(m);
      row.named += m.named; row.of += m.of;
      perEngine[k].named += m.named; perEngine[k].of += m.of;
    });
    return row;
  });
  const total = perEngine.reduce(function (a, e) { return { named: a.named + e.named, of: a.of + e.of }; }, { named: 0, of: 0 });
  const counted = perQuestion.some(function (row) { return row.cells.some(function (c) { return c.counted; }); });
  return { perEngine: perEngine, perQuestion: perQuestion, total: total, counted: counted };
}

function arRadii(ringCount) {
  const g = AR_GEOMETRY;
  if (ringCount === 1) return [g.singleRadius];
  const step = (g.outerRadius - g.innerRadius) / (ringCount - 1);
  const out = [];
  for (let k = 0; k < ringCount; k += 1) out.push(g.innerRadius + step * k);
  return out;
}

// Mark diameter in viewBox units: limited by the ring spacing and the arc between spokes.
function arMarkUnits(record) {
  const g = AR_GEOMETRY;
  const radii = arRadii(record.engines.length);
  const n = record.questions.length;
  const arc = radii[0] * ((360 - g.gapDegrees) / n) * Math.PI / 180;
  const ring = radii.length > 1 ? radii[1] - radii[0] : g.markMax / g.markRatio;
  return Math.min(g.markMax, ring * g.markRatio, arc * g.markRatio);
}

function arMarkPixels(record, widthPx) {
  return arMarkUnits(record) * widthPx / AR_GEOMETRY.viewBox;
}

// The table form replaces the wheel whenever the wheel's marks would be smaller than 8 pixels.
function arFormFor(record, widthPx) {
  return arMarkPixels(record, widthPx) < AR_GEOMETRY.minMarkPixels ? "table" : "wheel";
}

function arPoint(angle, radius) {
  const g = AR_GEOMETRY, a = angle * Math.PI / 180;
  return [g.center + radius * Math.sin(a), g.center - radius * Math.cos(a)];
}

function arCirclePath(x, y, r) {
  return "M " + arNum(x - r) + " " + arNum(y) + " a " + arNum(r) + " " + arNum(r) + " 0 1 0 " + arNum(2 * r) + " 0 a " + arNum(r) + " " + arNum(r) + " 0 1 0 " + arNum(-2 * r) + " 0 Z";
}

function arMarkPath(state, angle, radius, size) {
  const g = AR_GEOMETRY;
  const p = arPoint(angle, radius);
  if (state === "named") return arCirclePath(p[0], p[1], size / 2);
  if (state === "not_named") return arCirclePath(p[0], p[1], size / 2 - g.openStroke / 2);
  const a = angle * Math.PI / 180, half = size / 2;
  const dx = Math.cos(a) * half, dy = Math.sin(a) * half;
  return "M " + arNum(p[0] - dx) + " " + arNum(p[1] - dy) + " L " + arNum(p[0] + dx) + " " + arNum(p[1] + dy);
}

function arMarkAttrs(state) {
  const g = AR_GEOMETRY, c = AR_PALETTE;
  if (state === "named") return ' class="bw-ar__mark bw-ar__mark--named" fill="' + c.accent + '"';
  if (state === "not_named") return ' class="bw-ar__mark bw-ar__mark--open" fill="' + c.paper + '" stroke="' + c.inkSecondary + '" stroke-width="' + g.openStroke + '"';
  return ' class="bw-ar__mark bw-ar__mark--bar" fill="none" stroke="' + c.inkSecondary + '" stroke-width="' + g.barStroke + '" stroke-linecap="round"';
}

function arGlyph(state) {
  const c = AR_PALETTE;
  const d = state === "named" ? arCirclePath(8, 8, 5) : state === "not_named" ? arCirclePath(8, 8, 4.25) : "M 3 8 L 13 8";
  const paint = state === "named" ? ' fill="' + c.accent + '"' : state === "not_named" ? ' fill="' + c.paper + '" stroke="' + c.inkSecondary + '" stroke-width="1.5"' : ' fill="none" stroke="' + c.inkSecondary + '" stroke-width="2.5" stroke-linecap="round"';
  return '<svg class="bw-ar__glyph" viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false"><path class="bw-ar__glyph-' + state.replace("_", "-") + '" d="' + d + '"' + paint + "/></svg>";
}

function arWords(record) {
  const repeats = Number(record.repeats) || 0;
  const threshold = repeats ? Math.ceil(repeats * 2 / 3) : 0;
  return {
    named: repeats > 1 ? "Named in at least " + threshold + " of " + repeats + " runs" : "Named",
    notNamed: repeats > 1 ? "Named in fewer than " + threshold + " of " + repeats + " runs" : "Not named",
    unavailable: "No valid answer"
  };
}

function arAlt(record, stats) {
  const engines = record.engines.length === 5 ? "the five engines (" + arList(record.engines) + ")" : arList(record.engines);
  const lead = record.sample ? AR_SAMPLE_LABEL + ": " : "";
  return lead + record.subject + " was named in " + stats.total.named + " of " + stats.total.of + " valid answers to " + record.questions.length + " buyer questions on " + engines + ", " + record.caption.release + ", answers captured " + arDates(record.caption.dates) + ".";
}

function arSvg(record, stats, id) {
  const g = AR_GEOMETRY, c = AR_PALETTE;
  const radii = arRadii(record.engines.length);
  const n = record.questions.length;
  const step = (360 - g.gapDegrees) / n;
  const size = arMarkUnits(record);
  const angleOf = function (i) { return g.gapDegrees / 2 + step * (i + 0.5); };
  const out = [];
  out.push('<svg class="bw-ar__svg" viewBox="0 0 ' + g.viewBox + " " + g.viewBox + '" role="img" aria-labelledby="' + id + '-alt" focusable="false">');
  out.push('<title id="' + id + '-alt">' + arEscape(arAlt(record, stats)) + "</title>");
  out.push('<g class="bw-ar__spokes" aria-hidden="true">');
  for (let i = 0; i < n; i += 1) {
    const a = arPoint(angleOf(i), radii[0] - g.spokeInset), b = arPoint(angleOf(i), radii[radii.length - 1] + g.spokeOutset);
    out.push('<path class="bw-ar__spoke" d="M ' + arNum(a[0]) + " " + arNum(a[1]) + " L " + arNum(b[0]) + " " + arNum(b[1]) + '" fill="none" stroke="' + c.line + '" stroke-width="1" vector-effect="non-scaling-stroke"/>');
  }
  out.push("</g>");
  radii.forEach(function (r, k) {
    const start = arPoint(g.gapDegrees / 2, r), end = arPoint(360 - g.gapDegrees / 2, r);
    out.push('<g class="bw-ar__ring bw-ar__ring--' + (k + 1) + '" aria-hidden="true">');
    out.push('<path class="bw-ar__ring-line" d="M ' + arNum(start[0]) + " " + arNum(start[1]) + " A " + arNum(r) + " " + arNum(r) + " 0 1 1 " + arNum(end[0]) + " " + arNum(end[1]) + '" fill="none" stroke="' + c.dataBlue + '" stroke-width="1.5" vector-effect="non-scaling-stroke"/>');
    stats.perQuestion.forEach(function (row, i) {
      const state = row.cells[k].state;
      out.push('<path d="' + arMarkPath(state, angleOf(i), r, size) + '"' + arMarkAttrs(state) + "/>");
    });
    out.push("</g>");
  });
  out.push("</svg>");
  return out.join("");
}

function arCount(cell) {
  if (cell.state === "unavailable") return "No valid answer";
  if (!cell.counted) return cell.state === "named" ? "Named" : "Not named";
  return cell.named + " of " + cell.of;
}

function arTable(record, stats, id) {
  const words = arWords(record);
  const hidden = function (cell) { return cell.state === "named" ? words.named : cell.state === "not_named" ? words.notNamed : words.unavailable; };
  const out = [];
  out.push('<div class="bw-table-wrap bw-ar__table-form" id="' + id + '-table" role="region" aria-label="' + arEscape(record.subject + ", answer record as a table") + '" tabindex="0">');
  out.push('<table class="bw-table bw-table--stack bw-ar__table">');
  out.push('<caption>' + arEscape(arCaptionLine(record, stats)) + "</caption>");
  out.push('<thead><tr><th scope="col">Buyer question, in the Index wording</th>');
  record.engines.forEach(function (engine) { out.push('<th scope="col" class="bw-num">' + arEscape(engine) + "</th>"); });
  if (record.engines.length > 1) out.push('<th scope="col" class="bw-num">All engines</th>');
  out.push("</tr></thead><tbody>");
  record.questions.forEach(function (q, i) {
    const row = stats.perQuestion[i];
    out.push('<tr><th scope="row">' + arEscape(q.text) + "</th>");
    row.cells.forEach(function (cell, k) {
      out.push('<td class="bw-num" data-label="' + arEscape(record.engines[k]) + '"><span class="bw-ar__cell">' + arGlyph(cell.state) + '<span class="bw-visually-hidden">' + arEscape(hidden(cell)) + ": </span>" + arEscape(arCount(cell)) + "</span></td>");
    });
    if (record.engines.length > 1) out.push('<td class="bw-num" data-label="All engines">' + (stats.counted ? row.named + " of " + row.of : row.named + " of " + row.of + " engines") + "</td>");
    out.push("</tr>");
  });
  out.push("</tbody>");
  out.push('<tfoot><tr><th scope="row">All buyer questions</th>');
  stats.perEngine.forEach(function (e, k) { out.push('<td class="bw-num" data-label="' + arEscape(record.engines[k]) + '">' + e.named + " of " + e.of + "</td>"); });
  if (record.engines.length > 1) out.push('<td class="bw-num" data-label="All engines">' + stats.total.named + " of " + stats.total.of + "</td>");
  out.push("</tr></tfoot></table></div>");
  return out.join("");
}

function arCaptionLine(record, stats) {
  return record.subject + " in " + record.caption.release + ": " + record.caption.category + ", answers captured " + arDates(record.caption.dates) + ". Named in " + stats.total.named + " of " + stats.total.of + " valid answers.";
}

function arLegend(record) {
  const words = arWords(record);
  return '<ul class="bw-ar__legend">' +
    "<li>" + arGlyph("named") + "<span>" + arEscape(words.named) + "</span></li>" +
    "<li>" + arGlyph("not_named") + "<span>" + arEscape(words.notNamed) + "</span></li>" +
    "<li>" + arGlyph("unavailable") + "<span>" + arEscape(words.unavailable) + "</span></li></ul>";
}

function arRingLabels(record) {
  const count = record.engines.length;
  const out = ['<ol class="bw-ar__rings bw-ar__rings--' + count + '" aria-label="Rings from the center out">'];
  record.engines.forEach(function (engine, k) { out.push('<li class="bw-ar__ring-label bw-ar__ring-label--' + count + "-" + (k + 1) + '">' + arEscape(engine) + "</li>"); });
  out.push("</ol>");
  return out.join("");
}

function arDraw(record, options) {
  const o = options || {};
  const problems = arValidate(record);
  if (problems.length) throw new Error("Answer record not drawn: " + problems.join("; "));
  const id = String(o.id || "bw-ar").replace(/[^A-Za-z0-9_-]/g, "");
  const stats = arStats(record);
  const svg = arSvg(record, stats, id);
  const table = arTable(record, stats, id);
  const legend = arLegend(record);
  const c = record.caption;
  const title = record.subject + ": named in " + stats.total.named + " of " + stats.total.of + " valid answers";
  const sample = record.sample ? '<p class="bw-ar__sample">' + AR_SAMPLE_LABEL + "</p>" : "";
  const note = o.note ? '<p class="bw-ar__note">' + arEscape(o.note) + "</p>" : "";
  const toggle = '<button type="button" class="bw-button bw-button--text bw-ar__toggle" aria-expanded="false" aria-controls="' + id + '-table" hidden>Read as a table</button>';
  const caption = '<figcaption class="bw-ar__caption">' + note + legend + toggle + '<p class="bw-ar__title">' + arEscape(title) + "</p>" +
    '<p class="bw-ar__meta">' + arEscape(c.release + ". " + c.category + ". Answers captured " + arDates(c.dates) + ". Base: " + c.base + ".") +
    ' Source: <a href="' + arEscape(c.source_url) + '">' + arEscape(c.source_label || "the published record") + "</a>.</p></figcaption>";
  // The outer element is the size container; the figure inside sets the wheel beside its caption
  // when the container is wide enough, and above it otherwise.
  const html = '<div class="bw-ar' + (o.animate ? " bw-ar--animate" : "") + (o.wide ? " bw-ar--wide" : "") + (record.engines.length === 1 ? " bw-ar--single" : "") + (record.sample ? " bw-ar--sample" : "") + '" id="' + id + '" data-bw-answer-record data-mark-units="' + arNum(arMarkUnits(record)) + '" data-viewbox="' + AR_GEOMETRY.viewBox + '">' +
    '<figure class="bw-ar__figure">' + sample +
    '<div class="bw-ar__wheel">' + svg + arRingLabels(record) + "</div>" +
    table + caption + "</figure></div>";
  return { html: html, svg: svg, table: table, legend: legend, caption: caption, alt: arAlt(record, stats), stats: stats, markUnits: arMarkUnits(record) };
}

// Wires the "Read as a table" control and the phone rule. Returns a cleanup function.
function arEnhance(figure) {
  if (!figure || figure.getAttribute("data-bw-ar-ready") === "1") return function () {};
  figure.setAttribute("data-bw-ar-ready", "1");
  const frame = figure;
  const wheel = figure.querySelector(".bw-ar__wheel");
  const form = figure.querySelector(".bw-ar__table-form");
  const toggle = figure.querySelector(".bw-ar__toggle");
  const units = Number(figure.getAttribute("data-mark-units")) || AR_GEOMETRY.markMax;
  const box = Number(figure.getAttribute("data-viewbox")) || AR_GEOMETRY.viewBox;
  let expanded = false;
  function wheelWidth() {
    const max = parseFloat(window.getComputedStyle(wheel).maxWidth);
    const width = frame.clientWidth;
    return isFinite(max) && max > 0 ? Math.min(width, max) : width;
  }
  function apply() {
    const table = units * wheelWidth() / box < AR_GEOMETRY.minMarkPixels;
    figure.setAttribute("data-form", table ? "table" : "wheel");
    if (table) { form.hidden = false; toggle.hidden = true; }
    else { form.hidden = !expanded; toggle.hidden = false; toggle.setAttribute("aria-expanded", expanded ? "true" : "false"); }
  }
  function onClick() { expanded = !expanded; apply(); }
  toggle.addEventListener("click", onClick);
  let observer = null, frameId = 0;
  function schedule() { if (frameId) return; frameId = window.requestAnimationFrame(function () { frameId = 0; apply(); }); }
  if (typeof window.ResizeObserver === "function") { observer = new window.ResizeObserver(schedule); observer.observe(frame); }
  else window.addEventListener("resize", schedule);
  apply();
  return function () {
    toggle.removeEventListener("click", onClick);
    if (observer) observer.disconnect(); else window.removeEventListener("resize", schedule);
    figure.removeAttribute("data-bw-ar-ready");
  };
}
// END answer-record core
root.BwAnswerRecord = { draw: arDraw, validate: arValidate, stats: arStats, markUnits: arMarkUnits, markPixels: arMarkPixels, formFor: arFormFor, enhance: arEnhance, engines: AR_ENGINES.slice(), version: "3.0.2" };
function init() { Array.prototype.forEach.call(document.querySelectorAll("[data-bw-answer-record]"), function (figure) { arEnhance(figure); }); }
if (typeof document !== "undefined") {
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
}
})(typeof window !== "undefined" ? window : globalThis);
